conditions.value_template:
{% if manager_plan_usable | bool(false) %}
{{ ((current_limit_a | float) > (manager_live_current_ceiling_a | float)) or
   ((ac_error_w | float | abs) > (feedback_deadband_w | float) and
    (((desired_limit_a | float) - (current_limit_a | float)) | abs) >= (minimum_correction_a | float) and
    (gate_age_seconds | float) >= ((capture_settle_seconds | float) if (desired_limit_a | float) > (current_limit_a | float) else (release_settle_seconds | float))) }}
{% else %}{{ (ac_error_w | float(0)) | abs > 60 and ((desired_limit_a | float(1)) - (current_limit_a | float(250))) | abs >= 1 }}{% endif %}

{% if manager_plan_usable | bool(false) %}
{{ (gate_age_seconds | float) >= (probe_settle_seconds | float) and
   (ac_error_w | float | abs) <= (feedback_deadband_w | float) and
   (inverter_w | float) >= (physical_ac_ceiling_w | float) - (feedback_deadband_w | float) and
   (actual_charge_a | float) >= (current_limit_a | float) - 1.5 and
   (current_limit_a | float) < (manager_live_current_ceiling_a | float) }}
{% else %}{{ (ac_error_w | float(0)) | abs <= 60 and (actual_charge_a | float(0)) >= ((current_limit_a | float(250)) - 1.5) and (current_limit_a | float(250)) < (bms_charge_limit_a | float(125)) and (not (manager_plan_usable | bool(false)) or (current_limit_a | float(250)) < (manager_live_current_ceiling_a | float(0))) }}{% endif %}
